// Builds the Metabase versions of the queries.
// sql/source/*.sql  (hardcoded [TEST] params, runnable in any SQL client)
//   -> sql/metabase/*.sql  (params come from Metabase variables)
//
// Run after editing any source query:  npm run build:sql
import { readFileSync, writeFileSync, readdirSync, mkdirSync } from "node:fs";

const SRC = "sql/source";
const OUT = "sql/metabase";

// Every variable is type Text and optional. Metabase drops [[ ... ]] when a
// variable is not supplied, so COALESCE falls back to the default.
const PARAMS_BLOCK = `params AS (
    -- Generated by scripts/build-metabase-sql.mjs. Do not edit here: edit sql/source/ and rebuild.
    -- Values come from Metabase variables (all type Text, none required).
    -- Metabase removes [[ ... ]] when a variable is not supplied, so COALESCE uses the default.
    SELECT
        COALESCE([[ lower({{distributor}})::text, ]]  NULL::text)    AS distributor,
        COALESCE([[ {{postcode}}::text, ]]            NULL::text)    AS postcode,
        COALESCE([[ upper({{nmi}})::text, ]]          NULL::text)    AS nmi,
        COALESCE([[ {{usage_kwh}}::numeric, ]]        NULL::numeric) AS usage_kwh,
        COALESCE([[ {{peak_share}}::numeric, ]]       NULL::numeric) AS peak_share,
        COALESCE([[ {{shoulder_share}}::numeric, ]]   NULL::numeric) AS shoulder_share,
        COALESCE([[ {{max_demand_kw}}::numeric, ]]    NULL::numeric) AS max_demand_kw,
        COALESCE([[ {{offer_source}}::text, ]]        'all'::text)   AS offer_source,
        COALESCE([[ {{lim}}::int, ]]                  20::int)       AS lim,
        COALESCE([[ {{cursor_cost}}::numeric, ]]      NULL::numeric) AS cursor_cost,
        COALESCE([[ {{cursor_offer_id}}::bigint, ]]   NULL::bigint)  AS cursor_offer_id
),

`;

// Other small, deliberate changes for the API (each must match exactly once)
const EDITS = {
  "04_plans.sql": [
    // Keyset cursor must round-trip exactly; JSON numbers lose precision.
    [
      "rk.annual_cost_inc_gst                                        AS _cursor_cost,",
      "rk.annual_cost_inc_gst::text                                  AS _cursor_cost,   -- text: exact keyset round-trip",
    ],
  ],
};

mkdirSync(OUT, { recursive: true });
const files = readdirSync(SRC).filter((f) => /^\d\d_.+\.sql$/.test(f)).sort();
if (files.length !== 5) throw new Error(`Expected 5 source files, found ${files.length}`);

for (const f of files) {
  let sql = readFileSync(`${SRC}/${f}`, "utf8");
  const start = sql.indexOf("params AS (");
  const end = sql.indexOf("-- [HARDCODED][F4]");
  if (start < 0 || end < 0 || end < start) throw new Error(`${f}: could not find the params block`);
  sql = sql.slice(0, start) + PARAMS_BLOCK + sql.slice(end);

  for (const [from, to] of EDITS[f] ?? []) {
    const n = sql.split(from).length - 1;
    if (n !== 1) throw new Error(`${f}: expected 1 match for edit, found ${n}: ${from}`);
    sql = sql.replace(from, to);
  }
  // Metabase is happier without a trailing semicolon
  sql = sql.replace(/;(\s*(--[^\n]*\n?)*\s*)$/, "$1");
  writeFileSync(`${OUT}/${f}`, sql);
  console.log(`built ${OUT}/${f}`);
}
